compliant.code:
import boto3
import json

sqs = boto3.client('sqs')

# Compliant: Encrypted queue with proper access policy
queue_policy = {
    "Version": "2012-10-17",
    "Statement": [
        {
            "Effect": "Allow",
            "Principal": {"AWS": "arn:aws:iam::123456789012:root"},
            "Action": "sqs:*",
            "Resource": "*"
        }
    ]
}

queue_url = sqs.create_queue(
    QueueName='secure-encrypted-queue',
    Attributes={
        'KmsMasterKeyId': 'alias/aws/sqs',
        'KmsDataKeyReusePeriodSeconds': '300',
        'Policy': json.dumps(queue_policy)
    }
)
